/*
 * MyCC — a minimal expression compiler.
 *
 * Compiles an arithmetic expression (+ - * / with parentheses and unary
 * minus) given as argv[1] into x86-64 Linux assembly on stdout. The
 * generated program returns the expression's value as its exit code.
 *
 * Usage: ./build/MyCC "1+2*3" > out.s && cc -o out out.s && ./out; echo $?
 */

#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>

static const char *src;

static void fail(const char *msg) {
    fprintf(stderr, "MyCC: error: %s\n", msg);
    exit(1);
}

static void skip_ws(void) {
    while (isspace((unsigned char)*src))
        src++;
}

static void compile_expr(void);

static long parse_number(void) {
    long v = 0;
    if (!isdigit((unsigned char)*src))
        fail("expected number");
    while (isdigit((unsigned char)*src)) {
        v = v * 10 + (*src - '0');
        src++;
    }
    return v;
}

/* Left value is in rax, right value in rdi (both popped off the stack). */
static void emit_binop(char op) {
    printf("    pop %%rdi\n");
    printf("    pop %%rax\n");
    switch (op) {
    case '+': printf("    add %%rdi, %%rax\n"); break;
    case '-': printf("    sub %%rdi, %%rax\n"); break;
    case '*': printf("    imul %%rdi, %%rax\n"); break;
    case '/': printf("    cqo\n    idiv %%rdi\n"); break;
    }
    printf("    push %%rax\n");
}

static void compile_primary(void) {
    skip_ws();
    if (*src == '(') {
        src++;
        compile_expr();
        skip_ws();
        if (*src != ')')
            fail("expected ')'");
        src++;
    } else {
        long v = parse_number();
        printf("    mov $%ld, %%rax\n", v);
        printf("    push %%rax\n");
    }
}

static void compile_unary(void) {
    skip_ws();
    if (*src == '-') {
        src++;
        compile_unary();
        printf("    pop %%rax\n");
        printf("    neg %%rax\n");
        printf("    push %%rax\n");
    } else {
        compile_primary();
    }
}

/* * and / bind tighter than + and - */
static void compile_term(void) {
    compile_unary();
    for (;;) {
        skip_ws();
        if (*src == '*') {
            src++;
            compile_unary();
            emit_binop('*');
        } else if (*src == '/') {
            src++;
            compile_unary();
            emit_binop('/');
        } else {
            return;
        }
    }
}

static void compile_expr(void) {
    compile_term();
    for (;;) {
        skip_ws();
        if (*src == '+') {
            src++;
            compile_term();
            emit_binop('+');
        } else if (*src == '-') {
            src++;
            compile_term();
            emit_binop('-');
        } else {
            return;
        }
    }
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s \"<expression>\"\n", argv[0]);
        return 1;
    }
    src = argv[1];

    printf("    .globl main\n");
    printf("main:\n");
    printf("    push %%rbp\n");
    printf("    mov %%rsp, %%rbp\n");

    compile_expr();

    skip_ws();
    if (*src != '\0')
        fail("unexpected trailing input");

    printf("    pop %%rax\n");
    printf("    mov %%rbp, %%rsp\n");
    printf("    pop %%rbp\n");
    printf("    ret\n");
    return 0;
}
